INSERT INTO sign_in_sheet_print_row (
    job_id, row_index, seq_no, person_name, agency_name, shift_name, created_at
) VALUES (
    #{jobId}, #{rowIndex}, #{seqNo}, #{personName}, #{agencyName}, #{shiftName}, NOW()
)

mapper.select:
SELECT j.country_code AS countryCode, j.work_date AS workDate, COUNT(DISTINCT j.id) AS jobCount, COUNT(r.id) AS personCount, GROUP_CONCAT(DISTINCT j.warehouse ORDER BY j.warehouse SEPARATOR '||') AS warehousesCsv FROM sign_in_sheet_print_job j LEFT JOIN sign_in_sheet_print_row r ON r.job_id = j.id WHERE 1=1
AND j.work_date >= #{fromDate}
AND j.work_date <= #{toDate}
GROUP BY j.country_code, j.work_date ORDER BY j.work_date DESC, j.country_code ASC
